from pathlib import Path
import json,numpy as np,pandas as pd
R=Path(__file__).resolve().parent

def main():
 b=json.loads((R/'results/baseline_summary.json').read_text());a=json.loads((R/'results/ablation_audit.json').read_text());d=pd.read_csv(R/'results/ablation_metrics.csv');d['family']=d.method.str.split('_').str[0];d['excitation']=d.run.str.split('_').str[-1];d['physical_group']=d.run.str.split('_').str[-2]
 primary=d[(d.phase=='task')&(d.target=='estimator')&(d.horizon_s==.1)];agg=primary.groupby(['family','kind'])[['velocity_rmse','omega_rmse']].mean();detail=d.groupby(['family','kind','excitation','physical_group','phase','target','horizon_s'])[['velocity_rmse','omega_rmse']].mean().reset_index();detail.to_csv(R/'results/ablation_group_metrics.csv',index=False)
 lines=['# R7 JEPA适应研究：基线恢复诊断与慢参数门控','','本轮完成四条新Gazebo诊断飞行及冻结模型的停止/原始/门控更新消融。没有开启学习控制；研究目标尚未达到。R6的7/8旧恢复失败仍保留，新批是否通过见下表。候选时间配置修复只用于实验，不推广到原项目。','','## 基线与恢复','','四条都复用seed2、5.55kg开发条件，不是四个未见参数组。学习影子进程关闭，高频记录保持；同种子不等于完整状态分叉。旧71–72s与新91–92s分别评价；位置门仍max(1.1×45–48s RMSE,2cm)，速度5cm/s。','','|条件|位置界cm|旧窗估计峰值/真实RMSE cm|旧通过|延长窗估计峰值/真实RMSE cm|延长通过|首次连续2s回界(68s后)|','|---|---:|---:|---|---:|---|---:|']
 for r in b['rows']:
  o=r['windows']['old_final'];e=r['windows']['extended_final'];lines.append(f"|{r['run']}|{r['position_bound_m']*100:.3f}|{o['estimated_peak_m']*100:.3f}/{o['truth_rmse_m']*100:.3f}|{o['passed']}|{e['estimated_peak_m']*100:.3f}/{e['truth_rmse_m']*100:.3f}|{e['passed']}|{r['first_continuous_2s_recovery_s']}|")
 lines+=['','真实误差用无噪声navsat、实际EKF参考原点、地图投影及实际发布命令离线计算；不是相对预窗的位移。与Gazebo真实位移作中心化交叉检验见truth_frame_validation.json。后来短时回界不代表持续稳定，更不能改写旧窗失败。共同d110位置界对照见baseline_summary.json，避免不同预窗界掩盖差异。','']
 for p in b['pairs']:lines.append(f"- {p['kind']}：0ms相对110ms真实RMSE变化，旧窗{p['truth_old_rmse_change_pct']:+.2f}%，延长窗{p['truth_extended_rmse_change_pct']:+.2f}%（负值才改善）。")
 lines+=['','R6完整复核见DIAG_R6_zh.md：七条失败全为位置，非速度/饱和/安全退出；seed2激励前13个一秒窗仅2个满足同门。三类预测器共享基线控制飞行，不能分别声称监督/JEPA控制失败；预测门则都未通过。发布加速度补偿及原生参数补偿均为零。新纯悬停也失败，排除“必须由激励或学习控制引起”的解释；关闭影子进程仍失败，排除影子进程是必要原因，但不证明其所有时序影响为零。','','GPS与IMU均使用当前hrt时间戳，110ms延迟可疑；本次干预结果不支持将归零作为充分修复。现阶段证据支持原生噪声/估计/闭环基线及峰值门统计行为共同需要处理，尚未把更具体机制确认为根因。不得把JEPA分数改善拿来抵消位置不稳定。','','## 冻结骨干的适应消融','','训练预算新增0；同一八条R6轨迹、相同24个慢系数与初始化统计、同样输入与输出限幅。七个预测器×八轨迹不是56个独立试验。监督/JEPA各3个网络初始化，表内为各完整轨迹RMSE的等权算术平均，未把滑窗作独立样本。100ms，58–67.5s独立任务阶段，估计器标签：','','|模型|更新|速度RMSE m/s|角速度RMSE rad/s|','|---|---|---:|---:|']
 for (family,kind),row in agg.iterrows():lines.append(f"|{family}|{kind}|{row.velocity_rmse:.6f}|{row.omega_rmse:.6f}|")
 gates=[]
 for family in ['physics','supervised','jepa']:
  off=agg.loc[(family,'stopped')]
  for kind in ['original','gated']:
   on=agg.loc[(family,kind)];v=100*(1-on.velocity_rmse/off.velocity_rmse);w=100*(1-on.omega_rmse/off.omega_rmse);gates.append(dict(family=family,kind=kind,velocity_improvement_pct=v,omega_improvement_pct=w,aggregate_both_10pct=bool(min(v,w)>=10)))
 lines+=['','|模型|更新|速度改善%|角速度改善%|聚合双10%|','|---|---|---:|---:|---|']
 for g in gates:lines.append(f"|{g['family']}|{g['kind']}|{g['velocity_improvement_pct']:.2f}|{g['omega_improvement_pct']:.2f}|{g['aggregate_both_10pct']}|")
 audits=a['audits'];updated=sum(x['gated_updates']>0 for x in audits);stress=pd.DataFrame(a['stress']);latent=pd.DataFrame(a['latent_diagnostics']);latent['family']=latent.method.str.split('_').str[0]
 lines+=['',f"门控有更新的模型×轨迹组合{updated}/{len(audits)}；原更新每组合{min(x['original_updates'] for x in audits)}–{max(x['original_updates'] for x in audits)}次，门控{min(x['gated_updates'] for x in audits)}–{max(x['gated_updates'] for x in audits)}次。更少更新是保守机制的代价，不包装成同等适应效果。200/400ms、真值绝对误差、主动/常规与质量/CoM分组详见原始ablation_metrics.csv和ablation_group_metrics.csv；不挑单一指标替代原双10%门。",'',f"51–53s、0.3m/s²合成标签脉冲的持久W差：原更新最大{stress[stress.kind=='original'].W_difference.max():.6f}，门控最大{stress[stress.kind=='gated'].W_difference.max():.6f}。这是标签敏感性反例，非物理风实验；若门控全冻结导致零污染，也不能称成功识别了参数。",'']
 for fam,z in latent.groupby('family'):lines.append(f"- {fam}潜变量诊断：维度标准差均值{z.latent_mean_std.min():.5f}–{z.latent_mean_std.max():.5f}，协方差有效秩{z.effective_rank.min():.2f}–{z.effective_rank.max():.2f}/24。局部轨迹低有效秩不等于全分布严格塌缩，但非塌缩损失存在也不保证24方向信息充分。")
 lines+=['','## 为什么目前没有JEPA优势','','训练覆盖仅四条轨迹、每物理族一个种子，无舵机动态变化；在线只有近期历史与四维名义回归量。主动回归秩2/4、常规3/4，对任意6×4读出最多分别约12/24、18/24方向达到登记信息阈值；这不是完整质量/CoM/惯量可观秩。W只修改读出，不条件化潜空间演化。原JEPA后12epoch联合训练，与冻结表示后训练物理读出的论文流程不同；只有12epoch直接状态目标，对照有24；同更新数但约2.7倍训练时间，不能称严格算力公平。本轮不加训练掩盖这些结构和数据问题。','','双区间门控检查跨区间稳定性，减少可疑慢更新；它不解决信息缺失。构造d=XΔW可使参数变化与动作相关外扰产生完全相同可见残差，数值差为0；一致性门同样接受构造的持续扰动。四个行为测试通过，其中该不可区分反例是明确的能力边界，不是软件故障。','','## 验证、交付与下一道门','','四条新飞行的原生消费接口、零补偿、饱和、落地/解锁状态、资源和日志完整性以各outcome/native记录为准。重复启动参数记录导致一次审计误报，原失败和源码留档，修复后重审同一日志；没有重飞。见AMENDMENTS_zh.md。',f"离线消融耗时{a['wall_s']:.2f}s，限额120s，骨干文件/内存哈希保持一致；更新CPU耗时见ablation_timing.csv。原在线推理延迟沿用R6结果，本轮离线计时不能冒称在线端到端延迟。",'','已交付代码、两份预登记、数据/模型定义、全组原始指标、来源哈希和本地复现包。没有修改原Controller/PX4脏文件，没有硬件访问、主飞控改动、远程覆盖或强推。','','下一步必须先建立在当前原生噪声下可稳定满足原位置门的基线，并用独立实验检验估计噪声模型/闭环影响；不能放宽旧门宣称成功。其次在新开发数据中增加受限垂向/独立轴激励、质量/CoM/惯量/舵机变化和参数阶跃，验证信息方向；再用完整未见参数组测试结构化环境条件模型、冻结读出训练及严格算力配额。最后补齐前瞻动作接口并先过oracle整体非退化门，才能逐步开启有限学习补偿。R7到此仍是诊断和保守更新原型，未达到免手调参自适应控制。']
 lines.insert(lines.index('## 为什么目前没有JEPA优势'), '最终双区间共同子空间均为2维，但系数相对差为1.093–4.765（门0.5）、余弦最高0.558（门0.8）。因此本次冻结由不一致触发，不能仅归因于没有任何共同可观方向。JEPA潜变量标准差约0.204–0.342，证据不支持将本次失败简单说成完全塌缩。')
 (R/'REPORT_zh.md').write_text('\n'.join(lines)+'\n');decision=dict(control_enabled=False,baseline_old_passes=sum(r['windows']['old_final']['passed'] for r in b['rows']),baseline_extended_passes=sum(r['windows']['extended_final']['passed'] for r in b['rows']),gated_updated_combinations=updated,aggregate_prediction_gates=gates,goal_complete=False,stage_complete=True,independent_new_flights=len(b['rows']),new_training_steps=0);(R/'results/decision.json').write_text(json.dumps(decision,indent=2));print(json.dumps(decision,indent=2))
if __name__=='__main__':main()
